(function(){
'use strict';
const M=window.QFModel,I=window.QFImport,V=window.QFVault;
const $=s=>document.querySelector(s),root=$('#app'),sheet=$('#sheet');
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',pie:'<path d="M10 3a9 9 0 1 0 11 11H10z"/><path d="M14 2v8h8a9 9 0 0 0-8-8z"/>',trend:'<path d="M3 3v18h18M6 16l5-5 4 2 6-8"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 8V5a2 2 0 0 1 2-2h13M16 11h5v5h-5a2.5 2.5 0 0 1 0-5z"/>',stocks:'<path d="M5 4v16M3 9h4v7H3zM12 2v20M10 5h4v9h-4zM19 4v16M17 11h4v6h-4z"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2"/><circle cx="15" cy="12" r="2"/><circle cx="9" cy="18" r="2"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',eyeoff:'<path d="m3 3 18 18M10 5a12 12 0 0 1 12 7 17 17 0 0 1-3 4M6 6a17 17 0 0 0-4 6s4 7 10 7a12 12 0 0 0 4-1"/>',moon:'<path d="M20.8 13A9 9 0 0 1 11 3.2 9 9 0 1 0 20.8 13z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2m-2-8-2 2M6 18l-2 2M4 4l2 2m12 12 2 2"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 16v5h16v-5"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',arrow:'<path d="m9 5 7 7-7 7"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',check:'<path d="m5 12 4 4 10-10"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',database:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>',share:'<path d="M12 16V3m-4 4 4-4 4 4M7 11H4v10h16V11h-3"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',flag:'<path d="M5 22V3c5-4 9 4 15 0v10c-6 4-10-4-15 0"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>'};
const icon=n=>'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">'+(icons[n]||icons.info)+'</svg>';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const finite=Number.isFinite,fmt=(n,d=0)=>finite(n)?n.toLocaleString('es-ES',{minimumFractionDigits:d,maximumFractionDigits:d}):'--';
let hide=true,theme='light';try{hide=localStorage.getItem('quijo-hide')!=='false';theme=localStorage.getItem('quijo-theme')||'light';}catch(_){}
document.documentElement.dataset.theme=theme;
const money=(v,d=0)=>hide?'&bull;&bull;&bull;&bull;':fmt(v,d)+' &euro;',percent=(v,d=2,sign=false)=>finite(v)?(sign&&v>0?'+':'')+fmt(v,d)+'%':'--',signClass=v=>v<0?'negative':'positive';
const monthLabel=(p,long=false)=>new Date(p+'-15T12:00:00Z').toLocaleDateString('es-ES',{month:long?'long':'short',...(long?{year:'numeric'}:{})}).replace('.','');
const dateLabel=d=>new Date(d+'T12:00:00Z').toLocaleDateString('es-ES',{day:'2-digit',month:'short',year:'numeric'}).replace('.','');
const views=[['inicio','home','Inicio'],['cartera','pie','Cartera'],['evolucion','trend','Evoluci&oacute;n'],['ahorro','wallet','Ahorro'],['acciones','stocks','Acciones'],['plan','flag','Plan mensual'],['fire','target','FIRE'],['datos','database','Datos y ajustes']];
let payload=null,data=null,envelope=null,persisted=false,pending=null,currentView='inicio',selectedBlock='equity',savingsYear=null,selectedMonth=null,ordinary=false,evoMode='financial',evoYear='all',heroMode='financial',stockQuery='',stockSort='weight',toastTimer,charts=new Map(),lastFocus=null;
const asset=p=>window.QFAssets?.[p]||'./assets/'+p;
const brand=()=>'<div class="brand"><img src="'+asset('icon.svg')+'" alt="" width="42" height="42"><div><b>quijo<span style="font-size:27px;color:var(--brand)">.</span></b><br><span>FINANZAS PERSONALES</span></div></div>';
const button=(act,label,ico='',cls='',attrs='')=>'<button type="button" data-act="'+act+'" class="btn '+cls+'" '+attrs+'>'+(ico?icon(ico):'')+label+'</button>';
const miniKpi=(label,value,sub='',ico='')=>'<div class="card"><div class="row between"><span class="label">'+label+'</span>'+(ico?icon(ico):'')+'</div><div class="kpi-value number">'+value+'</div><div class="kpi-sub">'+sub+'</div></div>';
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4000);}
function openSheet(title,body){lastFocus=document.activeElement;$('#sheet-content').innerHTML='<div class="sheet-header row between"><h2 class="sheet-title" id="dialog-title">'+title+'</h2><button type="button" class="icon-btn" data-act="close" aria-label="Cerrar">'+icon('close')+'</button></div><div class="sheet-body">'+body+'</div>';if(!sheet.open)sheet.showModal();sheet.scrollTop=0;}
function closeSheet(){sheet.close();$('#sheet-content').innerHTML='';if(lastFocus?.isConnected)lastFocus.focus();}
function errorSheet(e){openSheet('No se ha podido completar','<p class="error">'+esc(e.message||e)+'</p><p class="note">No se han sustituido tus datos por valores incompletos. Revisa el archivo y vuelve a intentarlo.</p>');}
function years(a){return [...new Set(a.map(x=>x.period.slice(0,4)))].sort().reverse();}
function makePayload(d){return {schema:'quijo-vault',version:1,currentDate:d.date,snapshots:{[d.date]:d},settings:{dcaTotal:null,goals:{account:null,moneyMarket:null,defensivePlus:null},fire:null}};}
function validatePayload(p){if(!p||p.schema!=='quijo-vault'||p.version!==1||!p.snapshots||typeof p.snapshots!=='object'||Array.isArray(p.snapshots))throw Error('Copia de seguridad no compatible.');const snaps={};if(Object.keys(p.snapshots).length>150)throw Error('Demasiados cierres en la copia.');for(const [d,s] of Object.entries(p.snapshots)){const n=I.validate(s);if(d!==n.date)throw Error('Fecha incoherente en la copia.');snaps[d]=n;}if(!snaps[p.currentDate])throw Error('No se encuentra el cierre actual.');const s=p.settings||{},g=s.goals||{};const clean=n=>finite(n)&&n>=0&&n<1e10?n:null;const goals={account:clean(g.account),moneyMarket:clean(g.moneyMarket),defensivePlus:clean(g.defensivePlus)};let f=null;if(s.fire){const x=s.fire;const ok=['age','spending','annualNewSavings','withdrawal','realReturn','reserve'].every(k=>finite(x[k]));if(ok&&x.age>=18&&x.age<=95&&x.spending>0&&x.annualNewSavings>=0&&x.withdrawal>=1&&x.withdrawal<=10&&x.realReturn>=-5&&x.realReturn<=10&&x.reserve>=0)f={age:x.age,spending:x.spending,annualNewSavings:x.annualNewSavings,withdrawal:x.withdrawal,realReturn:x.realReturn,reserve:x.reserve,includePensions:!!x.includePensions};}return {schema:'quijo-vault',version:1,currentDate:p.currentDate,snapshots:snaps,settings:{dcaTotal:clean(s.dcaTotal),goals,fire:f}};}
function selectData(){data=payload.snapshots[payload.currentDate];if(!savingsYear||!years(data.savings).includes(savingsYear))savingsYear=years(data.savings)[0]||data.date.slice(0,4);if(!selectedMonth||!data.savings.some(m=>m.period===selectedMonth&&m.period.startsWith(savingsYear)))selectedMonth=data.savings.filter(m=>m.period.startsWith(savingsYear)).at(-1)?.period||null;}
function heading(title,sub,extra=''){return '<div class="page-heading"><div><h1>'+title+'</h1><p>'+sub+'</p></div>'+extra+'</div>';}
function navigate(view){if(!views.some(x=>x[0]===view))view='inicio';currentView=view;if(sheet.open)closeSheet();history.replaceState(null,'','#'+view);render();window.scrollTo({top:0,behavior:'instant'});}
function render(){charts.clear();if(!data){renderOnboarding();return;}root.innerHTML='<aside class="sidebar">'+brand()+'<nav aria-label="Secciones">'+views.slice(0,5).map(([v,i,n])=>'<button type="button" class="side-btn '+(v===currentView?'active':'')+'" data-view="'+v+'">'+icon(i)+n+'</button>').join('')+'</nav><div class="side-divider"></div><nav>'+views.slice(5).map(([v,i,n])=>'<button type="button" class="side-btn '+(v===currentView?'active':'')+'" data-view="'+v+'">'+icon(i)+n+'</button>').join('')+'</nav><div class="sidebar-foot">TU DINERO, EN PERSPECTIVA<br><br>Lectura local del Excel.<br>Sin enviar tus datos.<br><br>V1.1 &middot; '+(persisted?'Archivo cifrado':'Sesi&oacute;n temporal')+'</div></aside><div class="shell"><header class="topbar"><div class="mobile-brand">'+brand()+'</div><div class="top-title"><strong>Tu espacio financiero</strong>Datos al '+dateLabel(data.date)+'</div><div class="top-actions"><span class="pill '+(persisted?'good':'caution')+'">'+icon(persisted?'lock':'info')+(persisted?'Guardado cifrado':'Solo esta sesi&oacute;n')+'</span><button type="button" class="icon-btn" data-act="privacy" aria-label="'+(hide?'Mostrar importes':'Ocultar importes')+'" aria-pressed="'+hide+'">'+icon(hide?'eyeoff':'eye')+'</button><button type="button" class="icon-btn" data-act="theme" aria-label="Cambiar tema">'+icon(theme==='dark'?'sun':'moon')+'</button><button type="button" class="icon-btn" data-act="menu" aria-label="Plan, FIRE y ajustes">'+icon('settings')+'</button>'+button('import','Importar cierre','upload','import-top')+'</div></header><main id="main" class="page">'+({inicio:overview,cartera:portfolio,evolucion:evolution,ahorro:savingsView,acciones:stocksView,plan:planView,fire:fireView,datos:dataView}[currentView])()+'</main><p class="footer-note">Quijo &middot; Datos importados, no cotizaciones en tiempo real. Crecimiento patrimonial y rentabilidad son magnitudes distintas.</p></div><nav class="mobile-nav" aria-label="Navegaci&oacute;n principal">'+views.slice(0,5).map(([v,i,n])=>'<button type="button" data-view="'+v+'" class="'+(v===currentView?'active':'')+'" '+(v===currentView?'aria-current="page"':'')+'>'+icon(i)+'<span>'+n+'</span></button>').join('')+'</nav>';}
function chartLine(id,input,opts={}){if(!input.length)return '<p class="empty-text">Todav&iacute;a no hay datos para esta vista.</p>';let pts=input.map(p=>({...p}));const normalized=opts.monetary&&hide;if(normalized){const base=pts.find(p=>p.value>0)?.value||1;pts=pts.map(p=>({...p,value:p.value/base*100}));}charts.set(id,{original:input,pts,opts,normalized});const W=640,H=opts.height||250,L=opts.noAxis?10:57,R=22,T=20,B=32,pw=W-L-R,ph=H-T-B;let min=Math.min(...pts.map(p=>p.value)),max=Math.max(...pts.map(p=>p.value));if(opts.zero){min=Math.min(0,min);max=Math.max(0,max);}if(max===min){max+=1;min-=1;}const range=max-min;max+=range*.12;min-=range*.12;const x=i=>L+i/(Math.max(1,pts.length-1))*pw,y=v=>T+(max-v)/(max-min)*ph;let html='<svg class="chart" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="'+esc(opts.label||'Evolucion de los datos registrados')+'">';for(let i=0;i<4;i++){const v=min+(max-min)*i/3,yy=y(v);html+='<line class="gridline" x1="'+L+'" y1="'+yy+'" x2="'+(W-R)+'" y2="'+yy+'"/>';if(!opts.noAxis){const label=opts.percent?fmt(v,0)+'%':normalized?fmt(v,0):fmt(v/1000,0)+'k';html+='<text x="'+(L-10)+'" y="'+(yy+4)+'" text-anchor="end">'+label+'</text>';}}const path=pts.map((p,i)=>(i?'L':'M')+x(i).toFixed(2)+' '+y(p.value).toFixed(2)).join(' ');const color=opts.color||'var(--brand)';html+='<path d="'+path+' L'+x(pts.length-1)+' '+(H-B)+' L'+L+' '+(H-B)+'Z" fill="'+color+'" opacity=".08"/><path d="'+path+'" fill="none" stroke="'+color+'" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"/>';const every=Math.max(1,Math.ceil(pts.length/5));for(let i=0;i<pts.length;i++){const p=pts[i],label=opts.percent?percent(p.value,2,true):normalized?fmt(p.value,1)+' (base 100)':money(p.value,0);html+='<circle cx="'+x(i)+'" cy="'+y(p.value)+'" r="'+(i===pts.length-1?5:3)+'" fill="'+color+'"/>';const textLabel=p.period.length===7?monthLabel(p.period)+(pts.length>12?' '+p.period.slice(2,4):''):p.period;if(i%every===0||i===pts.length-1)html+='<text x="'+x(i)+'" y="'+(H-7)+'" text-anchor="middle">'+esc(textLabel)+'</text>';html+='<circle class="chart-target" cx="'+x(i)+'" cy="'+y(p.value)+'" r="13" fill="transparent" tabindex="0" role="button" data-chart="'+id+'" data-point="'+i+'" aria-label="'+esc(textLabel)+': '+label+'"><title>'+esc(textLabel)+' '+label+'</title></circle>';}return html+'</svg><div class="chart-readout" id="read-'+id+'"><span>'+esc(input[0].period)+' &rarr; '+esc(input.at(-1).period)+'</span><span>'+(normalized?'Base 100 &middot; importes ocultos':opts.percent?'% registrado':'Toca un punto')+'</span></div>';}
function bars(id,points,opts={}){if(!points.length)return '<p class="empty-text">Sin meses registrados.</p>';charts.set(id,{original:points,pts:points,opts,normalized:false});const W=640,H=230,L=45,R=10,T=25,B=32,pw=W-L-R,ph=H-T-B,lo=Math.min(0,...points.map(p=>p.value)),hi=Math.max(0.1,...points.map(p=>p.value)),range=hi-lo,min=lo-range*.13,max=hi+range*.12,y=v=>T+(max-v)/(max-min)*ph,step=pw/points.length,zero=y(0);let html='<svg class="chart" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="'+esc(opts.label||'Grafico mensual')+'">';for(let i=0;i<4;i++){let v=lo+(hi-lo)*i/3;html+='<line class="gridline" x1="'+L+'" y1="'+y(v)+'" x2="'+(W-R)+'" y2="'+y(v)+'"/><text x="'+(L-6)+'" y="'+(y(v)+4)+'" text-anchor="end">'+(opts.percent?fmt(v,0)+'%':fmt(v/1000,0)+'k')+'</text>';}html+='<line x1="'+L+'" x2="'+(W-R)+'" y1="'+zero+'" y2="'+zero+'" stroke="var(--line)"/>';points.forEach((p,i)=>{const xx=L+step*i+step*.2,width=step*.6,yy=Math.min(zero,y(p.value)),height=Math.abs(zero-y(p.value));const value=opts.percent?percent(p.value,1,true):money(p.value,0);html+='<g class="chart-target" tabindex="0" role="button" data-chart="'+id+'" data-point="'+i+'" aria-label="'+esc(monthLabel(p.period,true))+': '+value+'"><rect x="'+(L+step*i)+'" y="'+T+'" width="'+step+'" height="'+(ph+B)+'" fill="transparent"/><rect x="'+xx+'" y="'+yy+'" width="'+width+'" height="'+Math.max(1,height)+'" rx="5" fill="'+(p.value<0?'var(--negative)':'var(--brand)')+'" opacity="'+(opts.selected===p.period?'1':'.68')+'"/><text x="'+(xx+width/2)+'" y="'+(H-8)+'" text-anchor="middle">'+esc(monthLabel(p.period))+'</text><title>'+esc(monthLabel(p.period,true))+' '+value+'</title></g>';});return html+'</svg>';}
function donut(block,compact=false){const aa=M.allocation(data),chosen=aa.find(b=>b.key===block),r=85,circ=2*Math.PI*r;let off=0,svg='<div class="donut-box donut"><svg viewBox="0 0 280 280" role="img" aria-label="Distribucion por bloques">';aa.forEach(b=>{const len=circ*b.pct/100,angle=(off+len/2)/circ*2*Math.PI-Math.PI/2;svg+='<circle class="seg" cx="140" cy="140" r="'+r+'" fill="none" stroke="'+b.color+'" stroke-width="40" stroke-dasharray="'+Math.max(0,len-1.7)+' '+(circ-Math.max(0,len-1.7))+'" stroke-dashoffset="'+(-off)+'" transform="rotate(-90 140 140)" role="button" tabindex="0" data-block="'+b.key+'" aria-label="'+esc(b.name)+': '+percent(b.pct)+'" opacity="'+(!block||block===b.key?1:.42)+'"/>';if(b.pct>=4)svg+='<text class="wedge-label" pointer-events="none" x="'+(140+r*Math.cos(angle))+'" y="'+(144+r*Math.sin(angle))+'" text-anchor="middle">'+percent(b.pct,1)+'</text>';off+=len;});svg+='<text class="center-kpi" x="140" y="135" text-anchor="middle">'+(chosen?percent(chosen.pct):'100%')+'</text><text class="center-label" x="140" y="158" text-anchor="middle">'+(chosen?esc(chosen.name):'TU CARTERA')+'</text></svg></div>';const list='<div class="legend-list">'+aa.map(b=>'<button type="button" class="legend-item '+(block===b.key?'active':'')+'" data-block="'+b.key+'"><span class="dot" style="background:'+b.color+'"></span><span class="name">'+esc(b.name)+'</span><strong>'+percent(b.pct)+'</strong></button>').join('')+'</div>';return compact?svg+list:'<div class="allocation-card">'+svg+list+'</div>';}
function overview(){const t=M.totals(data),aa=M.allocation(data),eq=M.sum(aa.filter(b=>['equity','stocks'].includes(b.key)).map(b=>b.pct)),sv=M.savings(data,data.date.slice(0,4)),hist=M.historical(data,heroMode).slice(-12),last=hist.at(-1),prev=hist.at(-2),change=prev?.value?(last.value/prev.value-1)*100:null,month=data.savings.at(-1),ms=month?M.savingMonth(month):null;return heading('Tu dinero, en perspectiva.','Una sola mirada a lo que tienes y c&oacute;mo evoluciona.','<span class="badge">'+dateLabel(data.date)+'</span>')+'<div class="stack"><div class="dashboard-top"><section class="card hero"><div class="hero-top"><div><p class="label">'+(heroMode==='financial'?'PATRIMONIO FINANCIERO':'PATRIMONIO NETO')+'</p><h2 class="number">'+money(t[heroMode==='financial'?'financial':'net'])+'</h2><span class="badge">'+percent(change,2,true)+' vs observaci&oacute;n anterior</span></div><div class="segmented"><button type="button" data-hero="financial" class="'+(heroMode==='financial'?'active':'')+'">Financiero</button><button type="button" data-hero="net" class="'+(heroMode==='net'?'active':'')+'">Neto</button></div></div><div style="margin-top:24px">'+chartLine('home',hist,{monetary:true,noAxis:true,color:'var(--lime)',height:175})+'</div><p class="tiny muted" style="margin-top:13px">Incluye ahorro y cambios de valor. No es rentabilidad.</p></section><div class="kpi-grid">'+miniKpi('Inversi&oacute;n',money(t.invested),'Sin efectivo en cuentas','stocks')+miniKpi('Ahorro '+data.date.slice(0,4),percent(sv.rate,1),sv.count+' meses registrados','wallet')+miniKpi('Liquidez disponible',money(t.available),'Excluye saldos de uso restringido','lock')+miniKpi('Renta variable',percent(eq,1),'Fondos, planes y acciones','pie')+'</div></div><div class="dashboard-bottom"><section class="card"><div class="row between"><h2>As&iacute; se reparte</h2><button type="button" class="btn quiet" data-view="cartera">Explorar '+icon('arrow')+'</button></div>'+donut(null,true)+'</section><div class="stack"><section class="card"><div class="row between"><div><p class="label">&Uacute;LTIMO MES REGISTRADO</p><h2 style="margin-top:6px;text-transform:capitalize">'+(ms?esc(monthLabel(ms.period,true)):'Sin datos')+'</h2></div>'+icon('wallet')+'</div>'+(ms?'<div class="metric-grid" style="margin:20px 0"><div><span class="label">Ingresos</span><b>'+money(ms.income)+'</b></div><div><span class="label">Gastos</span><b>'+money(ms.expenses)+'</b></div><div><span class="label">Ahorro</span><b class="'+signClass(ms.net)+'">'+money(ms.net)+'</b></div></div><div class="row between"><span class="muted small">Tasa de ahorro</span><b>'+percent(ms.rate,1)+'</b></div><div class="progress" style="margin:10px 0 15px"><span style="width:'+Math.max(0,Math.min(100,ms.rate||0))+'%"></span></div><button type="button" class="btn wide" data-month-detail="'+ms.period+'">Abrir este mes '+icon('arrow')+'</button>':'<p class="empty-text">Importa los datos de ahorro.</p>')+'</section><section class="card"><div class="row between"><h2>Tu pr&oacute;ximo paso</h2>'+icon('flag')+'</div><p class="small muted" style="margin:11px 0 16px">Revisa la caja, el reparto del DCA y el origen de las aportaciones sin confundir traspasos con ahorro nuevo.</p><button type="button" class="btn wide" data-view="plan">Ver plan mensual '+icon('arrow')+'</button></section></div></div><p class="note">Hist&oacute;rico importado tal como est&aacute; registrado. Antes de septiembre de 2026 hay observaciones a mitad de mes; no se presentan como cierres homog&eacute;neos.</p></div>';}
function portfolio(){const aa=M.allocation(data);if(!aa.some(b=>b.key===selectedBlock))selectedBlock=aa[0]?.key||'equity';const b=aa.find(x=>x.key===selectedBlock),items=M.contents(data,selectedBlock),t=M.totals(data);const notes={equity:'World agrupa Vanguard y Fidelity. Los dos planes de pensiones se agrupan en una sola posici&oacute;n. Toca un producto para ver su detalle.',stocks:'La rentabilidad de las acciones es la de las posiciones abiertas, con los dividendos registrados; no una TWR del bloque.',defensive:'Se conserva la agrupaci&oacute;n del Excel: AXA es monetario; Ostrum, renta fija ultracorta; DNCA, renta fija flexible; Gamma, mixto. Este bloque no equivale a efectivo garantizado.',cash:'La cifra contable incluye todos los saldos marcados como efectivo en el Excel. Los saldos de uso restringido se separan al calcular liquidez disponible.',bitcoin:'Exposici&oacute;n a Bitcoin mediante ETP. No se trata de efectivo ni de un fondo monetario.',gold:'Exposici&oacute;n a oro mediante ETC. Su valor puede fluctuar.'};return heading('Tu cartera.','Pesos sobre el patrimonio financiero, sin mezclarlo con la vivienda.','<span class="badge">'+data.positions.length+' posiciones</span>')+'<div class="stack"><section class="card"><div class="row between"><h2>Distribuci&oacute;n por activos</h2><span class="small muted">Toca un segmento</span></div>'+donut(selectedBlock)+'</section><section class="card" id="block-detail"><div class="row between"><div><p class="label">BLOQUE SELECCIONADO</p><h2 style="margin-top:6px">'+esc(b?.name)+'</h2></div><div class="table-amount"><strong style="font-size:26px">'+percent(b?.pct)+'</strong><p class="muted small">'+money(b?.value)+'</p></div></div><div class="table-list" style="margin-top:12px">'+items.map(g=>'<div class="table-row"><button type="button" data-product="'+esc(g.id)+'"><div class="table-name">'+esc(g.name)+'</div><div class="table-meta">'+percent(M.pct(g.value,t.financial))+' de la cartera total</div><div class="progress" style="width:min(100%,260px);margin-top:10px"><span style="width:'+g.pct+'%;background:'+b.color+'"></span></div></button><div class="table-amount"><strong>'+percent(g.pct)+'</strong><div class="table-meta">del bloque</div><div class="small muted" style="margin-top:5px">'+money(g.value)+'</div></div></div>').join('')+'</div><p class="note" style="margin-top:18px">'+(notes[selectedBlock]||'Revisa la clasificaci&oacute;n de estos productos.')+'</p></section><div class="row between wrap"><p class="tiny muted">Desgloses recalculados sobre cada bloque. Puede haber diferencias de redondeo.</p>'+button('share','Versi&oacute;n p&uacute;blica','share')+'</div></div>';}
function savingsView(){const y=savingsYear||data.date.slice(0,4),s=M.savings(data,y,ordinary),current=s.months.find(m=>m.period===selectedMonth)||s.months.at(-1),yr=years(data.savings);const points=s.months.filter(m=>!hide||finite(m.rate)).map(m=>({period:m.period,value:hide?m.rate:m.net}));return heading('Cada mes cuenta.','Ingresos, gastos y ahorro, sin inventar categor&iacute;as que no est&aacute;n en el Excel.','<select id="savings-year" class="year-select" aria-label="A&ntilde;o de ahorro">'+yr.map(v=>'<option '+(v===y?'selected':'')+'>'+v+'</option>').join('')+'</select>')+'<div class="stack"><div class="row between wrap"><div class="segmented"><button type="button" data-saving-mode="total" class="'+(!ordinary?'active':'')+'">Total</button><button type="button" data-saving-mode="ordinary" class="'+(ordinary?'active':'')+'">Ordinario</button></div><span class="pill">'+s.count+' meses con datos</span></div><div class="grid3">'+miniKpi('Ingresos '+y,money(s.income),ordinary?'Excluye extraordinarios':'Registrados en el Excel')+miniKpi('Gastos '+y,money(s.expenses),ordinary?'Excluye extraordinarios':'Registrados en el Excel')+miniKpi('Ahorro '+y,percent(s.rate,1),money(s.net)+' de excedente')+'</div><section class="card"><div class="row between wrap"><div><h2>'+(!hide?'Ahorro mensual':'Tasa de ahorro mensual')+'</h2><p class="small muted">Toca una barra o el mes para ver qu&eacute; ocurri&oacute;.</p></div><span class="badge">'+(ordinary?'Ordinario':'Total')+'</span></div><div style="margin-top:15px">'+bars('savings-bars',points,{percent:hide,selected:current?.period,action:'savings'})+'</div><div class="month-grid">'+s.months.map(m=>'<button type="button" class="month-btn '+(current?.period===m.period?'active':'')+'" data-month="'+m.period+'">'+esc(monthLabel(m.period))+'</button>').join('')+'</div></section>'+(current?'<section class="card month-detail"><div class="row between"><div><p class="label">MES SELECCIONADO</p><h2 style="margin-top:5px">'+esc(monthLabel(current.period,true))+'</h2></div><b class="'+signClass(current.net)+'" style="font-size:27px">'+percent(current.rate,1)+'</b></div><div class="metric-grid" style="margin:20px 0"><div><span class="label">Ingresos</span><b>'+money(current.income)+'</b></div><div><span class="label">Gastos</span><b>'+money(current.expenses)+'</b></div><div><span class="label">Ahorro</span><b class="'+signClass(current.net)+'">'+money(current.net)+'</b></div></div><button type="button" class="btn wide" data-month-detail="'+current.period+'">Ver ordinarios y extraordinarios '+icon('arrow')+'</button></section>':'')+'<p class="note">&ldquo;Ordinario&rdquo; significa que se han descontado las partidas marcadas como extraordinarias en el Excel. No implica que todos los ingresos restantes sean recurrentes.</p></div>';}
function stocksView(){const s=M.stockTotals(data),t=M.totals(data);return heading('Tus acciones.','El sat&eacute;lite, con cada posici&oacute;n en su contexto.','<span class="badge">'+s.count+' compa&ntilde;&iacute;as</span>')+'<div class="stack"><section class="card"><div class="metric-grid"><div><span class="label">Valor del bloque</span><b>'+money(s.value)+'</b></div><div><span class="label">Peso financiero</span><b>'+percent(M.pct(s.value,t.financial))+'</b></div><div><span class="label">Resultado / coste</span><b class="'+signClass(s.rate)+'">'+percent(s.rate,2,true)+'</b></div></div><p class="small muted" style="margin-top:13px">Posiciones abiertas + dividendos registrados. No es rentabilidad anualizada ni TWR.</p></section><div class="searchbar"><input id="stock-search" type="search" placeholder="Buscar compa&ntilde;&iacute;a o ticker" aria-label="Buscar acciones" value="'+esc(stockQuery)+'"><select id="stock-sort" aria-label="Ordenar acciones"><option value="weight" '+(stockSort==='weight'?'selected':'')+'>Por peso</option><option value="return" '+(stockSort==='return'?'selected':'')+'>Por resultado</option><option value="name" '+(stockSort==='name'?'selected':'')+'>Por nombre</option></select></div><div id="stock-list" class="stock-grid">'+stockCards()+'</div><p class="note">Los importes y el coste medio se leen del Excel en euros. No se consulta cotizaci&oacute;n en directo ni se recalcula el cambio de divisa. Los s&iacute;mbolos de marca se sirven localmente.</p></div>';}
function logo(p){const allowed=['MSFT','META','MA','MCD','MC','SPGI','AMZN','AIR'];return allowed.includes(p.ticker)?'<img class="stock-logo" src="'+asset('logos/'+p.ticker+'.svg')+'" alt="'+esc(p.displayName)+'">':'<span class="stock-logo row" aria-hidden="true">'+icon('stocks')+'</span>';}
function stockCards(){let ss=data.positions.filter(p=>p.kind==='stock'&&((p.name+' '+p.ticker).toLowerCase().includes(stockQuery.toLowerCase()))),tot=M.stockTotals(data).value;ss.sort((a,b)=>stockSort==='name'?a.name.localeCompare(b.name):stockSort==='return'?(b.returnSinceEntry??-Infinity)-(a.returnSinceEntry??-Infinity):b.value-a.value);return ss.length?ss.map(p=>'<button type="button" class="stock-card" data-stock="'+esc(p.id)+'"><div class="row">'+logo(p)+'<div class="info"><b>'+esc(p.displayName)+'</b><span>'+esc(p.ticker||'Acci&oacute;n')+'</span></div><div class="stock-return '+signClass(p.returnSinceEntry)+'">'+percent(p.returnSinceEntry*100,2,true)+'</div></div><div class="progress"><span style="width:'+M.pct(p.value,tot)+'%"></span></div><div class="stock-footer"><span>'+percent(M.pct(p.value,tot))+' del bloque</span><strong>'+money(p.value)+'</strong></div></button>').join(''):'<p class="empty-text">No hay coincidencias.</p>';}
function evolution(){const yy=evoYear==='all'?data.date.slice(0,4):evoYear;const est=evoMode==='returns';const pts=est?M.returns(data,yy).map(x=>({...x,value:x.cumulative})):M.historical(data,evoMode).filter(p=>evoYear==='all'||p.period.startsWith(evoYear));const opts=years(data.history);const labels={financial:'Patrimonio financiero',investment:'Valor invertido',net:'Patrimonio neto',returns:'Rentabilidad estimada del Excel'};const rr=M.returns(data,yy);return heading('El camino recorrido.','Datos registrados, con sus fechas y sus l&iacute;mites.','<select id="evolution-year" class="year-select" aria-label="Periodo de evoluci&oacute;n"><option value="all" '+(evoYear==='all'?'selected':'')+'>Todo</option>'+opts.map(y=>'<option '+(evoYear===y?'selected':'')+'>'+y+'</option>').join('')+'</select>')+'<div class="stack"><div class="segmented">'+Object.entries(labels).map(([k,n])=>'<button type="button" data-evo="'+k+'" class="'+(evoMode===k?'active':'')+'">'+(k==='returns'?'Estimaci&oacute;n %':n.replace('Patrimonio ','').replace('Valor ',''))+'</button>').join('')+'</div><section class="card"><div class="row between wrap"><div><h2>'+labels[evoMode]+'</h2><p class="small muted">'+(est?'Solo '+yy+' &middot; no validada como TWR':'Incluye aportaciones y retiradas')+'</p></div><span class="badge">'+pts.length+' observaciones</span></div><div style="margin-top:17px">'+chartLine('evolution',pts,{monetary:!est,percent:est,zero:est,height:270,label:labels[evoMode]})+'</div><p class="note '+(est?'warn':'')+'" style="margin-top:17px">'+(est?'Aproximaci&oacute;n: (valor final &minus; valor inicial &minus; flujo registrado) / valor inicial. Se encadenan esas variaciones. No se conocen todas las fechas de flujo; tampoco se han auditado todos los traspasos. No se presenta como rentabilidad real validada.':'La curva representa tama&ntilde;o patrimonial, no rendimiento de la inversi&oacute;n. Las observaciones anteriores a septiembre de 2026 no son cierres homog&eacute;neos. No se dibujan cotizaciones diarias inventadas.')+'</p></section>'+(est?'<section class="card"><h2>Estimaciones mensuales de '+yy+'</h2><div style="margin-top:12px">'+bars('returns-bars',rr,{percent:true,action:'returns'})+'</div><div class="table-scroll"><table class="summary-table"><thead><tr><th>Mes</th><th>Estimaci&oacute;n</th><th>Encadenada</th></tr></thead><tbody>'+rr.map(r=>'<tr><td>'+esc(monthLabel(r.period))+'</td><td class="'+signClass(r.value)+'">'+percent(r.value,2,true)+'</td><td>'+percent(r.cumulative,2,true)+'</td></tr>').join('')+'</tbody></table></div></section>':'<section class="card"><h2>Qu&eacute; falta para comparar bien</h2><p class="small muted" style="margin-top:10px;line-height:1.8">Cierres uniformes, aportaciones externas separadas de traspasos y un benchmark con las mismas fechas y divisa. Hasta entonces no publicamos Sharpe, alfa ni &ldquo;batimos al mercado&rdquo;.</p></section>')+'</div>';}
function planView(){const settings=payload.settings,dt=settings.dcaTotal,t=M.totals(data),g=settings.goals||{},goalSum=M.sum(Object.values(g)),current=[t.available,M.sum(data.positions.filter(p=>p.group==='axa').map(p=>p.value)),M.sum(data.positions.filter(p=>p.group==='gamma').map(p=>p.value))];return heading('El plan, sin improvisar.','Presupuesto mensual y reservas. Los objetivos no alteran los saldos reales.')+'<div class="stack"><section class="card"><div class="row between"><h2>Aportaciones mensuales</h2><span class="badge">'+(dt===null?'Configura tu presupuesto':money(dt))+'</span></div><div class="table-list" style="margin-top:10px">'+M.dca.map(x=>'<div class="table-row"><div><p class="table-name">'+esc(x.name)+'</p><div class="progress" style="width:220px;max-width:100%;margin-top:8px"><span style="width:'+x.pct+'%"></span></div></div><div class="table-amount"><strong>'+percent(x.pct)+'</strong><p class="table-meta">'+(dt===null?'Sin importe configurado':money(dt*x.pct/100,2))+'</p></div></div>').join('')+'</div><div class="divider"></div><label class="field">Presupuesto DCA mensual (&euro;)<input id="dca-input" type="number" inputmode="decimal" min="0" step="1" placeholder="Introduce tu presupuesto privado" value="'+(dt??'')+'"></label><div style="margin-top:12px">'+button('save-dca','Guardar presupuesto','check','primary')+'</div><p class="note" style="margin-top:14px">El presupuesto de compras no equivale al ahorro nuevo. Un traspaso entre fondos financia una compra, pero no aumenta el patrimonio financiero. Los dos PP est&aacute;n agrupados en el reparto.</p></section><section class="card"><div class="row between"><h2>Reservas por funci&oacute;n</h2><span class="badge">'+(goalSum?money(goalSum)+' objetivo':'Sin objetivos')+'</span></div><div class="table-list">'+[['Cuenta disponible','account',current[0]],['Monetario (AXA)','moneyMarket',current[1]],['Defensivo+ (Gamma)','defensivePlus',current[2]]].map(([n,k,v])=>'<div class="table-row"><div><p class="table-name">'+n+'</p><p class="table-meta">'+(g[k]?percent(M.pct(v,g[k]),0)+' del objetivo':'Define un objetivo abajo')+'</p><div class="progress" style="width:210px;max-width:100%;margin-top:8px"><span style="width:'+Math.min(100,M.pct(v,g[k]||Infinity))+'%"></span></div></div><div class="table-amount"><strong>'+money(v)+'</strong><p class="table-meta">'+(g[k]?'de '+money(g[k]):'saldo actual')+'</p></div></div>').join('')+'</div><div class="form-grid" style="margin-top:15px">'+[['Cuenta','account'],['Monetario','moneyMarket'],['Defensivo+','defensivePlus']].map(([n,k])=>'<label class="field">Objetivo '+n+' (&euro;)<input type="number" inputmode="decimal" id="goal-'+k+'" min="0" step="1" value="'+(g[k]??'')+'" placeholder="Sin definir"></label>').join('')+'</div><div style="margin-top:12px">'+button('save-goals','Guardar objetivos','check','primary')+'</div><p class="note" style="margin-top:15px">Gamma se muestra separado de la liquidez: asumir riesgo no convierte un producto en fondo de emergencia. La tarjeta de uso restringido no cuenta como caja disponible.</p></section></div>';}
function fireView(){const f=payload.settings.fire;const fields=[['age','Edad actual','number','18','95','1'],['spending','Gasto anual objetivo (&euro; de hoy)','number','1','10000000','1'],['annualNewSavings','Ahorro anual NUEVO para FIRE (&euro;)','number','0','10000000','1'],['reserve','Reserva fuera del objetivo (&euro;)','number','0','100000000','1'],['withdrawal','Retirada inicial supuesta (%)','number','1','10','.05'],['realReturn','Rentabilidad REAL supuesta (%)','number','-5','10','.1']];const defaults={withdrawal:3.5,realReturn:3,reserve:0};let result='';if(f){const m=M.fire(data,f),central=m.scenarios[1];result='<section class="card hero"><p class="label">ESCENARIO CENTRAL, NO PREDICCI&Oacute;N</p><h2>'+percent(m.progress,1)+' del objetivo</h2><div class="row between wrap"><span>Capital considerado: '+money(m.base)+'</span><b>Objetivo: '+money(m.target)+'</b></div><div class="divider" style="background:#ffffff25"></div><p>'+ (central.years===null?'No se alcanza en 60 a&ntilde;os bajo este supuesto.':'Se alcanza aproximadamente a los <b>'+fmt(central.age)+' a&ntilde;os</b>, con aportaciones anuales al final del a&ntilde;o.')+'</p></section><section class="card"><h2>Sensibilidad al escenario</h2><div class="table-scroll"><table class="summary-table"><thead><tr><th>Rentabilidad real</th><th>A&ntilde;os</th><th>Edad orientativa</th></tr></thead><tbody>'+m.scenarios.map(s=>'<tr><td>'+percent(s.r,1)+'</td><td>'+(s.years===null?'&gt;60':fmt(s.years))+'</td><td>'+(s.age===null?'--':fmt(s.age))+'</td></tr>').join('')+'</tbody></table></div><p class="small muted" style="margin-top:13px">Fuera del capital considerado: fondo asignado al hijo ('+money(m.child)+'), reserva elegida y '+(f.includePensions?'ninguna exclusi&oacute;n de PP.':'planes de pensiones ('+money(m.excludedPensions)+').')+'</p></section>';}
return heading('Libertad, con supuestos claros.','Un simulador de escenarios. No una fecha garantizada de jubilaci&oacute;n.')+'<div class="stack">'+result+'<section class="card"><h2>Tu escenario privado</h2><p class="small muted" style="margin:8px 0 18px">Completa estos datos; no se deducen del DCA ni se publican en QuijoCartera.</p><div class="form-grid">'+fields.map(([k,n,t,min,max,step])=>'<label class="field">'+n+'<input id="fire-'+k+'" type="'+t+'" inputmode="decimal" min="'+min+'" max="'+max+'" step="'+step+'" value="'+(f?.[k]??defaults[k]??'')+'" required></label>').join('')+'</div><label class="checkline" style="margin-top:16px"><input type="checkbox" id="fire-pp" '+(f?.includePensions?'checked':'')+'>Incluir planes de pensiones en el capital, sin modelar cu&aacute;ndo se pueden rescatar.</label><div style="margin-top:16px">'+button('save-fire','Calcular escenarios','target','primary wide')+'</div><p class="note warn" style="margin-top:16px">Euros de hoy; rentabilidad real supuesta neta de comisiones. No incorpora fiscalidad del rescate, pensi&oacute;n p&uacute;blica, secuencia de retornos ni cambios de gasto. La retirada elegida no es una tasa segura garantizada. Ahorro nuevo excluye traspasos internos y ahorro destinado al hijo.</p></section></div>';}
function dataView(){const snaps=Object.keys(payload.snapshots).sort().reverse();return heading('Tus datos, bajo control.','Importa, revisa, conserva una copia y decide qu&eacute; compartir.')+'<div class="stack"><div class="data-grid"><section class="card"><p class="label">FUENTE ACTUAL</p><h2 style="margin-top:8px">'+dateLabel(data.date)+'</h2><p class="small muted" style="margin:10px 0;overflow-wrap:anywhere">'+esc(data.source.fileName)+'</p><div class="metric-grid"><div><span class="label">Posiciones</span><b>'+data.positions.length+'</b></div><div><span class="label">Hist&oacute;rico</span><b>'+data.history.length+'</b></div><div><span class="label">Meses ahorro</span><b>'+data.savings.length+'</b></div></div><div style="margin-top:16px">'+button('import','Importar nuevo Excel','upload','primary wide')+'</div></section><section class="card"><h2>Cierres guardados</h2><p class="small muted" style="margin:10px 0 15px">Cada importaci&oacute;n confirmada conserva una fotograf&iacute;a de las posiciones. Reimportar la misma fecha la sustituye solo tras confirmarlo.</p><label class="field">Fotograf&iacute;a activa<select id="snapshot-select">'+snaps.map(d=>'<option value="'+d+'" '+(data.date===d?'selected':'')+'>'+dateLabel(d)+'</option>').join('')+'</select></label><p class="note" style="margin-top:16px">Las observaciones de &ldquo;Seguimiento Cartera&rdquo; no reconstruyen las posiciones antiguas. Solo se conservan posiciones por fecha desde cada importaci&oacute;n real.</p></section></div><div class="data-grid"><section class="card stack-sm"><h2>Privacidad y copias</h2>'+(!persisted?button('create-vault','Guardar cifrado en este dispositivo','lock','primary wide'):'<p class="success">Archivo local cifrado. La clave no se guarda.</p>')+button('backup','Exportar copia cifrada','download','wide')+button('import','Restaurar copia / importar Excel','upload','wide')+button('lock','Bloquear pantalla','lock','wide')+button('forget','Eliminar datos de este dispositivo','close','danger wide')+'<p class="note">El almacenamiento del navegador puede borrarse. Exporta una copia y guarda tu contrase&ntilde;a: no hay recuperaci&oacute;n por email ni sincronizaci&oacute;n autom&aacute;tica. El bot&oacute;n del ojo oculta importes; no cifra por s&iacute; mismo.</p></section><section class="card stack-sm"><h2>QuijoCartera p&uacute;blica</h2><p class="small muted">Una salida independiente con porcentajes, productos y reparto del DCA. Nunca saldos, n&uacute;mero de acciones, ingresos, nombres personales ni presupuestos.</p>'+button('share','Revisar y exportar porcentajes','share','primary wide')+'<div class="divider"></div><h3>Instalar en el m&oacute;vil</h3><p class="small muted">Con la app publicada bajo HTTPS: en Safari, Compartir &rarr; A&ntilde;adir a pantalla de inicio. Abre primero la app instalada y carga el Excel desde ah&iacute;.</p>'+button('install-info','Gu&iacute;a de instalaci&oacute;n','info','wide')+'</section></div><section class="card"><h2>Calidad de los datos y metodolog&iacute;a</h2><ul class="data-list">'+data.warnings.map(w=>'<li>'+esc(w)+'</li>').join('')+'<li>Los resultados sin valor guardado se reconstruyen solo con las operaciones num&eacute;ricas admitidas por este importador. No es un motor completo de Excel.</li><li>No se publica ni se precarga ning&uacute;n Excel en el repositorio. El paquete de la app est&aacute; vac&iacute;o de importes privados.</li><li>Los saldos se agrupan por funci&oacute;n; &ldquo;RF y defensivos&rdquo; no significa &ldquo;capital garantizado&rdquo;.</li><li>Sharpe, comparaci&oacute;n con benchmark y TWR exacta no se calculan sin un registro fiable de fechas y flujos.</li></ul></section></div>';}
function renderOnboarding(){const has=!!envelope;root.innerHTML='<div class="onboarding"><header class="onboarding-head">'+brand()+'<div class="row"><span class="badge">V1.1 &middot; Local</span><button type="button" class="icon-btn" data-act="theme" aria-label="Cambiar tema">'+icon(theme==='dark'?'sun':'moon')+'</button></div></header><main id="main" class="landing-grid"><section class="landing-copy"><p class="label">MENOS PESTA&Ntilde;AS. M&Aacute;S PERSPECTIVA.</p><h1>Tu dinero.<br>Tu ritmo.<br>Tu <span style="color:var(--brand)">quijo.</span></h1><p>Convierte tu Excel de seguimiento en una visi&oacute;n clara de tu cartera, ahorro y patrimonio. Sin conectar el banco y sin enviar tus cifras a un servidor.</p><div class="security-strip"><span>'+icon('lock')+'Datos locales</span><span>'+icon('pie')+'Cartera interactiva</span><span>'+icon('wallet')+'Ahorro mes a mes</span></div></section><section><div class="empty-illustration"><p class="label" style="color:#afc8ba">TU ESPACIO FINANCIERO</p><div style="font-size:28px;font-weight:750;margin:10px 0">Todo en su sitio.</div><div class="mock" style="width:65%"></div><div class="mock" style="width:44%"></div><div class="grid3"><div class="mini"><div class="mock"></div><div class="mock"></div></div><div class="mini"><div class="mock"></div><div class="mock"></div></div><div class="mini"><div class="mock"></div><div class="mock"></div></div></div></div>'+(has?'<div class="card stack-sm"><h2>Tu archivo est&aacute; protegido</h2><p class="small muted">Introduce la contrase&ntilde;a de este dispositivo.</p><label class="field">Contrase&ntilde;a<input id="unlock-password" type="password" autocomplete="current-password"></label><div id="unlock-error"></div>'+button('unlock','Desbloquear','lock','primary wide')+button('import','Abrir otro Excel o copia','upload','wide')+button('forget','Borrar este archivo local','close','quiet wide')+'</div>':'<div class="dropzone" id="dropzone"><div class="upload-icon">'+icon('upload')+'</div><h2>Empieza por tu Excel</h2><p>Arrastra tu archivo de cierre mensual o selecci&oacute;nalo.<br>XLSX / copia JSON &middot; m&aacute;ximo 12 MB</p>'+button('import','Importar mi archivo','upload','primary wide')+'<p style="margin:12px 0 0">Primero revisas los datos. Despu&eacute;s decides si guardarlos.</p></div>')+'</section></main><p class="footer-note">Compatible con la plantilla de seguimiento de Quijo Finanzas. Sin cifras de demostraci&oacute;n ni cotizaciones inventadas. Los datos del dispositivo son privados; la app publicada en GitHub Pages ser&aacute; p&uacute;blica y comenzar&aacute; vac&iacute;a.</p></div>';const dz=$('#dropzone');if(dz){dz.addEventListener('dragover',e=>{e.preventDefault();dz.classList.add('drag');});dz.addEventListener('dragleave',()=>dz.classList.remove('drag'));dz.addEventListener('drop',e=>{e.preventDefault();dz.classList.remove('drag');const f=e.dataTransfer.files[0];if(f)handleFile(f);});}}
async function handleFile(file){if(file.size>12*1024*1024){errorSheet(Error('El archivo supera 12 MB.'));return;}openSheet('Leyendo en tu dispositivo','<p class="notice">Procesando el archivo localmente. No se est&aacute; subiendo.</p>');try{if(file.name.toLowerCase().endsWith('.json')){const j=JSON.parse(await file.text());if(j.schema==='quijo-encrypted'){V.check(j);pending={kind:'encrypted',envelope:j};openSheet('Restaurar copia cifrada','<div class="stack-sm"><p class="small muted">La copia solo se guardar&aacute; despu&eacute;s de desbloquearla y confirmar su contenido.</p><label class="field">Contrase&ntilde;a de la copia<input type="password" id="restore-password" autocomplete="current-password"></label><div id="restore-error"></div>'+button('restore-unlock','Abrir copia','lock','primary wide')+'</div>');return;}if(j.schema==='quijocartera-publica')throw Error('Esta exportacion solo tiene porcentajes. Usa el Excel o la copia cifrada para recuperar los importes.');}const d=await I.fromFile(file);pending={kind:'snapshot',data:d};previewImport();}catch(e){pending=null;errorSheet(e);}}
function previewImport(){if(pending?.kind!=='snapshot')return;const d=pending.data,t=M.totals(d),old=payload?.snapshots[d.date],historyExisting=data?.history||[],newPeriods=d.history.filter(m=>!historyExisting.some(p=>p.period===m.period)).length;openSheet('Revisa antes de guardar','<div class="stack"><p class="small muted">Lectura del archivo: <strong>'+esc(d.source.fileName)+'</strong></p><div class="metric-grid"><div><span class="label">Posiciones</span><b>'+d.positions.length+'</b></div><div><span class="label">Observaciones</span><b>'+d.history.length+'</b></div><div><span class="label">Meses nuevos</span><b>'+newPeriods+'</b></div></div><div class="soft"><div class="row between"><span class="small">Patrimonio financiero le&iacute;do</span><b>'+fmt(t.financial,2)+' &euro;</b></div><div class="row between" style="margin-top:9px"><span class="small">Importes de cuentas</span><b>'+fmt(t.cash,2)+' &euro;</b></div><p class="tiny muted" style="margin-top:8px">Vista privada de comprobaci&oacute;n.</p></div><label class="field">Confirma la fecha real de las posiciones<input type="date" id="import-date" value="'+d.date+'"></label><div class="notice">No uses TODAY() como fecha de estos saldos. Debe coincidir con el periodo del Excel. Las fechas antiguas no se convierten retrospectivamente en cierres de mes.</div>'+ (old?'<label class="checkline"><input id="replace-snapshot" type="checkbox">Confirmo que quiero actualizar el cierre ya guardado para esta fecha.</label>':'')+'<details class="collapsible"><summary>'+d.warnings.length+' notas de calidad</summary>'+d.warnings.map(w=>'<p class="note">'+esc(w)+'</p>').join('')+'</details><div id="import-error"></div>'+button('accept-import',persisted?'Confirmar y guardar cifrado':'Confirmar y abrir','check','primary wide')+'<p class="tiny muted">'+(persisted?'Se conserva el resto de los cierres guardados.':'Se abrir&aacute; en esta sesi&oacute;n. Despu&eacute;s puedes activar el guardado cifrado.')+'</p></div>');}
async function acceptImport(){if(pending?.kind!=='snapshot')return;const d=structuredClone(pending.data),date=$('#import-date').value;if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||date.slice(0,7)!==d.history.at(-1).period){$('#import-error').innerHTML='<p class="error">La fecha debe pertenecer al &uacute;ltimo periodo con datos del Excel.</p>';return;}if(payload?.snapshots[date]&&!$('#replace-snapshot')?.checked){$('#import-error').innerHTML='<p class="error">Confirma la sustituci&oacute;n del cierre existente.</p>';return;}d.date=date;let next=payload?structuredClone(payload):makePayload(d);if(payload){const last=payload.snapshots[Object.keys(payload.snapshots).sort().at(-1)];for(const key of ['history','savings']){const map=new Map(last[key].filter(x=>x.period<=date.slice(0,7)).map(x=>[x.period,x]));d[key].forEach(x=>map.set(x.period,x));d[key]=[...map.values()].sort((a,b)=>a.period.localeCompare(b.period));}next.snapshots[date]=d;next.currentDate=date;}next=validatePayload(next);if(persisted)await V.save(next);payload=next;pending=null;selectData();closeSheet();currentView='inicio';render();toast(persisted?'Cierre guardado cifrado.':'Excel abierto. Todavia no se ha guardado en el dispositivo.');}
async function persistNext(next){next=validatePayload(next);if(persisted)await V.save(next);payload=next;selectData();render();toast(persisted?'Cambios guardados.':'Cambios en esta sesion. Guarda cifrado para conservarlos.');}
function createVaultDialog(){if(!data)return;openSheet('Guardar de forma local','<div class="stack-sm"><p class="small muted">Los datos se guardar&aacute;n cifrados en este navegador. Usa una contrase&ntilde;a larga y &uacute;nica; no hay recuperaci&oacute;n si la olvidas.</p><label class="field">Contrase&ntilde;a (m&iacute;nimo 10 caracteres)<input id="vault-pass" type="password" autocomplete="new-password" minlength="10"></label><label class="field">Repite la contrase&ntilde;a<input id="vault-pass2" type="password" autocomplete="new-password"></label>'+(envelope&&!persisted?'<label class="checkline"><input id="overwrite-vault" type="checkbox">Ya existe otro archivo cifrado en este dispositivo. Confirmo que lo sustituyo por esta sesi&oacute;n.</label>':'')+'<div id="vault-error"></div>'+button('save-vault','Guardar cifrado','lock','primary wide')+'<p class="note">Cifrado local AES-GCM con clave derivada de la contrase&ntilde;a. No protege frente a un dispositivo comprometido, extensiones maliciosas o cambios maliciosos en el c&oacute;digo publicado. No ha recibido una auditor&iacute;a de seguridad independiente.</p></div>');}
async function saveVault(){const pass=$('#vault-pass').value,repeat=$('#vault-pass2').value;if(pass.length<10||pass!==repeat){$('#vault-error').innerHTML='<p class="error">Usa al menos 10 caracteres y repite la misma contrase&ntilde;a.</p>';return;}if(envelope&&!persisted&&!$('#overwrite-vault')?.checked){$('#vault-error').innerHTML='<p class="error">Debes confirmar que sustituyes el archivo local anterior.</p>';return;}await V.create(pass,payload);persisted=true;envelope=await V.read();closeSheet();render();toast('Datos guardados cifrados en este navegador. Exporta una copia de seguridad.');try{await navigator.storage?.persist?.();}catch(_){} }
async function unlockLocal(){try{const pass=$('#unlock-password').value,next=validatePayload(await V.unlock(pass,envelope));payload=next;persisted=true;selectData();render();}catch(e){if($('#unlock-error'))$('#unlock-error').innerHTML='<p class="error">'+esc(e.message)+'</p>';else throw e;}}
async function lockApp(){if(!persisted){openSheet('Sesi&oacute;n sin guardar','<div class="stack-sm"><p class="note warn">Si cierras esta sesi&oacute;n perder&aacute;s los cambios locales no guardados. Puedes volver a importar el Excel.</p>'+button('create-vault','Guardar cifrado antes','lock','primary wide')+button('discard-session','Cerrar sin guardar','close','danger wide')+'</div>');return;}V.lock();data=null;payload=null;pending=null;charts.clear();if(sheet.open)closeSheet();envelope=await V.read();render();}
function productDetail(id){const g=M.contents(data,selectedBlock).find(x=>x.id===id);if(!g)return;const t=M.totals(data);openSheet(esc(g.name),'<div class="stack"><div class="metric-grid"><div><span class="label">Valor</span><b>'+money(g.value)+'</b></div><div><span class="label">Del bloque</span><b>'+percent(g.pct)+'</b></div><div><span class="label">Del total</span><b>'+percent(M.pct(g.value,t.financial))+'</b></div></div><div class="table-list">'+g.items.map(p=>'<div class="table-row"><div><div class="table-name">'+esc(hide?(p.displayName||'Cuenta / saldo'):p.name)+'</div><p class="table-meta">'+(p.isin?esc(p.isin):p.kind==='pension'?'Plan de pensiones':p.ticker?esc(p.ticker):'Sin identificador verificado')+'</p>'+ (finite(p.returnSinceEntry)?'<p class="small '+signClass(p.returnSinceEntry)+'" style="margin-top:7px">'+percent(p.returnSinceEntry*100,2,true)+' registrada en origen</p>':'')+'</div><div class="table-amount"><b>'+money(p.value)+'</b><p class="table-meta">'+percent(M.pct(p.value,g.value))+' del grupo</p></div></div>').join('')+'</div><p class="note">Los resultados de entrada de cada producto no son rentabilidades anuales comparables: tienen distintas fechas y aportaciones. No se calcula una rentabilidad agregada del grupo mezclando esos porcentajes.</p><p class="provenance">Origen: '+g.items.map(p=>esc(p.source)).join(' | ')+'</p></div>');}
function stockDetail(id){const p=data.positions.find(x=>x.id===id);if(!p)return;const unreal=p.value-p.cost;openSheet(esc(p.displayName),'<div class="stack"><div class="row">'+logo(p)+'<div><p class="label">'+esc(p.ticker)+'</p><h2 class="'+signClass(p.returnSinceEntry)+'">'+percent(p.returnSinceEntry*100,2,true)+'</h2><p class="small muted">Resultado simple sobre el coste</p></div></div><div class="metric-grid"><div><span class="label">Valor actual</span><b>'+money(p.value,2)+'</b></div><div><span class="label">Coste</span><b>'+money(p.cost,2)+'</b></div><div><span class="label">Div. registrados</span><b>'+money(p.dividends,2)+'</b></div></div><div class="soft"><div class="tooltip-row"><span>Acciones</span><b>'+(hide?'&bull;&bull;&bull;&bull;':fmt(p.quantity,4))+'</b></div><div class="tooltip-row"><span>Precio medio de compra</span><b>'+money(p.unitCost,2)+'</b></div><div class="tooltip-row"><span>Precio de la observaci&oacute;n (EUR)</span><b>'+money(p.quantity?p.value/p.quantity:null,2)+'</b></div><div class="tooltip-row"><span>Plusval&iacute;a no realizada</span><b class="'+signClass(unreal)+'">'+money(unreal,2)+'</b></div></div><p class="note">F&oacute;rmula: (valor actual &minus; coste + dividendos registrados) / coste. No incluye operaciones ya cerradas que no figuran aqu&iacute;. El Excel no especifica si todos los dividendos est&aacute;n anotados brutos o netos.</p><p class="provenance">Origen: '+esc(p.source)+'</p></div>');}
function monthDetail(period){const raw=data.savings.find(m=>m.period===period);if(!raw)return;const total=M.savingMonth(raw),ord=M.savingMonth(raw,true);openSheet(esc(monthLabel(period,true)),'<div class="stack"><div class="row between"><p class="label">TASA DE AHORRO TOTAL</p><b style="font-size:30px" class="'+signClass(total.net)+'">'+percent(total.rate,1)+'</b></div><div class="table-scroll"><table class="summary-table"><thead><tr><th>Concepto</th><th>Total</th><th>Ordinario</th></tr></thead><tbody><tr><td>Ingresos</td><td>'+money(total.income)+'</td><td>'+money(ord.income)+'</td></tr><tr><td>Gastos</td><td>'+money(total.expenses)+'</td><td>'+money(ord.expenses)+'</td></tr><tr><td><b>Ahorro</b></td><td class="'+signClass(total.net)+'"><b>'+money(total.net)+'</b></td><td class="'+signClass(ord.net)+'"><b>'+money(ord.net)+'</b></td></tr><tr><td>Tasa</td><td>'+percent(total.rate,1)+'</td><td>'+percent(ord.rate,1)+'</td></tr></tbody></table></div><div class="soft"><p class="label">EXTRAORDINARIOS MARCADOS</p><div class="tooltip-row"><span>Ingresos extraordinarios</span><b>'+money(raw.extraIncome)+'</b></div><div class="tooltip-row"><span>Gastos extraordinarios</span><b>'+money(raw.extraExpenses)+'</b></div></div><p class="note">Se respeta tu clasificaci&oacute;n del Excel. No se crean desgloses por supermercado, ocio o vivienda sin esos movimientos.</p><p class="provenance">Origen: '+esc(raw.source)+'</p></div>');}
function shareDialog(){const p=M.publicExport(data);openSheet('Solo lo que quieres compartir','<div class="stack"><p class="notice">Esta exportaci&oacute;n solo contiene porcentajes, nombres de productos, identificadores y fecha. No contiene saldos, unidades, ingresos, nombres personales ni DCA en euros.</p><div class="share-preview"><p class="label">QUIJOCARTERA &middot; '+dateLabel(data.date)+'</p>'+p.blocks.map(b=>'<div class="tooltip-row"><span>'+esc(b.name)+'</span><b>'+percent(b.pct)+'</b></div>').join('')+'</div><div class="button-row">'+button('export-public','Guardar JSON p&uacute;blico','download','primary')+button('public-png','Guardar tarjeta PNG','share')+'</div><p class="note">Ocultar importes en pantalla no basta para publicar la app con datos precargados. Esta salida se genera mediante una lista permitida de campos.</p></div>');}
function download(name,body,type='application/json'){const blob=body instanceof Blob?body:new Blob([body],{type});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),30000);}
function publicPng(){const p=M.publicExport(data),c=document.createElement('canvas');c.width=1400;c.height=920;const x=c.getContext('2d');x.fillStyle='#102d2d';x.fillRect(0,0,1400,920);x.fillStyle='#e4eddb';x.font='bold 64px Arial';x.fillText('quijo.',75,115);x.font='22px Arial';x.fillStyle='#a5bbb0';x.fillText('QUIJOCARTERA  /  '+dateLabel(data.date),75,164);let start=-Math.PI/2;const cols=['#58ad8f','#a2be79','#8daac2','#d9c792','#df9663','#cdb752','#ccc'];p.blocks.forEach((b,i)=>{x.beginPath();x.arc(365,476,192,start,start+2*Math.PI*b.pct/100);x.lineWidth=73;x.strokeStyle=cols[i];x.stroke();start+=2*Math.PI*b.pct/100;x.fillStyle=cols[i];x.beginPath();x.arc(725,295+i*73,7,0,7);x.fill();x.fillStyle='#e4eddb';x.font='23px Arial';x.fillText(b.name,749,303+i*73);x.font='bold 29px Arial';x.textAlign='right';x.fillText(percent(b.pct).replace(/&[^;]+;/g,''),1320,303+i*73);x.textAlign='left';});x.fillStyle='#e4eddb';x.font='bold 58px Arial';x.textAlign='center';x.fillText('100%',365,485);x.fillStyle='#a5bbb0';x.font='17px Arial';x.fillText('COMPOSICION',365,521);x.textAlign='left';x.fillStyle='#a5bbb0';x.font='18px Arial';x.fillText('Datos de cierre. Solo porcentajes. No es una recomendacion de inversion.',75,810);x.font='21px Arial';x.fillStyle='#e4eddb';x.fillText('quijotefinanzas.com',75,859);c.toBlob(blob=>{if(blob)download('QuijoCartera-'+data.date+'.png',blob,'image/png');});}
async function action(name){switch(name){
case 'import':$('#import-file').value='';$('#import-file').click();break;
case 'close':pending=null;closeSheet();break;
case 'privacy':hide=!hide;try{localStorage.setItem('quijo-hide',String(hide));}catch(_){}if(sheet.open)closeSheet();render();maskFields();break;
case 'theme':theme=theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('quijo-theme',theme);}catch(_){}render();break;
case 'menu':openSheet('Tu espacio','<div class="stack-sm">'+views.slice(5).map(([v,i,n])=>'<button type="button" class="action-card" data-view="'+v+'">'+icon(i)+'<span class="text"><strong>'+n+'</strong></span>'+icon('arrow')+'</button>').join('')+button('import','Importar cierre','upload','wide')+button('share','Compartir porcentajes','share','wide')+button('lock','Bloquear','lock','wide')+'</div>');break;
case 'accept-import':await acceptImport();break;
case 'create-vault':createVaultDialog();break;
case 'save-vault':await saveVault();break;
case 'unlock':await unlockLocal();break;
case 'lock':await lockApp();break;
case 'discard-session':data=null;payload=null;pending=null;persisted=false;V.lock();charts.clear();closeSheet();render();break;
case 'forget':openSheet('Eliminar datos locales','<div class="stack-sm"><p class="note warn">Se borrar&aacute; el archivo cifrado de este navegador y los datos abiertos. No se borra tu Excel original. Exporta una copia antes si quieres conservar los ajustes.</p><label class="field">Escribe BORRAR para confirmar<input id="forget-confirm" autocomplete="off" placeholder="BORRAR"></label>'+button('confirm-forget','Eliminar de este dispositivo','close','danger wide')+'</div>');break;
case 'confirm-forget':if($('#forget-confirm').value!=='BORRAR'){toast('Escribe BORRAR para confirmar.');break;}await V.forget();V.lock();data=null;payload=null;envelope=null;persisted=false;pending=null;charts.clear();closeSheet();render();toast('Archivo local eliminado.');break;
case 'backup':if(!persisted){createVaultDialog();break;}await V.save(payload);download('Quijo-'+data.date+'.qf-backup.json',JSON.stringify(await V.read()));toast('Copia cifrada exportada. Conserva la contrasena fuera del archivo.');break;
case 'restore-unlock':{const pass=$('#restore-password').value;try{pending.payload=validatePayload(await V.unlock(pass,pending.envelope,false));pending.password=pass;openSheet('Confirma la restauraci&oacute;n','<div class="stack-sm"><p class="notice">La copia contiene '+Object.keys(pending.payload.snapshots).length+' cierres. La fecha activa es '+dateLabel(pending.payload.currentDate)+'.</p><p class="note warn">Restaurar sustituir&aacute; la colecci&oacute;n guardada en este navegador. No se mezcla autom&aacute;ticamente con la actual.</p><label class="checkline"><input type="checkbox" id="restore-confirm-check">Confirmo que quiero restaurar esta copia.</label>'+button('restore-confirm','Restaurar copia cifrada','check','primary wide')+'</div>');}catch(e){$('#restore-error').innerHTML='<p class="error">'+esc(e.message)+'</p>';}break;}
case 'restore-confirm':if(!$('#restore-confirm-check')?.checked){toast('Confirma la restauracion.');break;}await V.unlock(pending.password,pending.envelope);await V.storeEnvelope(pending.envelope);payload=pending.payload;envelope=pending.envelope;persisted=true;pending=null;selectData();closeSheet();render();toast('Copia restaurada.');break;
case 'share':shareDialog();break;
case 'export-public':download('QuijoCartera-publica-'+data.date+'.json',JSON.stringify(M.publicExport(data),null,2));toast('Exportacion publica sin importes.');break;
case 'public-png':publicPng();break;
case 'save-dca':{if(hide){toast('Muestra los importes para editar.');break;}const el=$('#dca-input'),v=Number(el.value);if(!el.value||!el.checkValidity()||!finite(v)||v>10000000){toast('Introduce un presupuesto valido.');break;}const next=structuredClone(payload);next.settings.dcaTotal=v;await persistNext(next);break;}
case 'save-goals':{if(hide){toast('Muestra los importes para editar.');break;}const next=structuredClone(payload);for(const k of ['account','moneyMarket','defensivePlus']){const e=$('#goal-'+k),v=e.value===''?null:Number(e.value);if(!e.checkValidity()||v>1e9)throw Error('Objetivo fuera de rango.');next.settings.goals[k]=v;}await persistNext(next);break;}
case 'save-fire':{if(hide){toast('Muestra los importes para editar.');break;}const next=structuredClone(payload),f={};for(const k of ['age','spending','annualNewSavings','reserve','withdrawal','realReturn']){const e=$('#fire-'+k);if(!e.value||!e.reportValidity())return;f[k]=Number(e.value);}f.includePensions=$('#fire-pp').checked;next.settings.fire=f;await persistNext(next);break;}
case 'install-info':openSheet('Llevar Quijo al iPhone','<div class="stack-sm"><h3>1. Publica solo la app</h3><p class="small muted">Sube los archivos de la carpeta de despliegue a un repositorio dedicado de GitHub Pages. No subas el Excel ni tus copias privadas.</p><h3>2. Abre el enlace HTTPS en Safari</h3><p class="small muted">Compartir &rarr; A&ntilde;adir a pantalla de inicio. Si aparece, activa &ldquo;Abrir como app web&rdquo;.</p><h3>3. Importa desde la app instalada</h3><p class="small muted">Selecciona el Excel desde Archivos, revisa y confirma. Activa el guardado cifrado y exporta una copia.</p><p class="note">El archivo HTML de prueba no instala una PWA. La primera carga necesita conexi&oacute;n; despu&eacute;s el c&oacute;digo se conserva para uso sin conexi&oacute;n. Un repositorio privado no hace privada una web de Pages.</p></div>');break;
}}
function maskFields(){if(!data||!hide)return;for(const sel of ['#dca-input','#goal-account','#goal-moneyMarket','#goal-defensivePlus','#fire-spending','#fire-annualNewSavings','#fire-reserve']){const el=$(sel);if(el){el.value='';el.disabled=true;el.placeholder='Muestra importes para editar';}}for(const act of ['save-dca','save-goals','save-fire']){const b=document.querySelector('[data-act="'+act+'"]');if(b)b.disabled=true;}}
// Re-rendered inputs are masked too, not just display labels.
const renderOriginal=render;render=function(){renderOriginal();maskFields();};
function handleChart(el){const chart=charts.get(el.dataset.chart),idx=Number(el.dataset.point),p=chart?.original[idx];if(!p)return;if(chart.opts.action==='savings'){selectedMonth=p.period;render();monthDetail(p.period);return;}if(chart.opts.action==='returns'){const r=M.returns(data,p.period.slice(0,4)).find(x=>x.period===p.period);openSheet('Estimaci&oacute;n de '+esc(monthLabel(p.period,true)),'<div class="stack-sm"><h2>'+percent(r.value,2,true)+'</h2><p class="notice">Rentabilidad mensual aproximada; no validada como TWR.</p><div class="tooltip-row"><span>Inversi&oacute;n inicial</span><b>'+money(r.start)+'</b></div><div class="tooltip-row"><span>Flujo registrado</span><b>'+money(r.flow)+'</b></div><div class="tooltip-row"><span>Inversi&oacute;n final</span><b>'+money(r.end)+'</b></div><p class="note">El movimiento registrado debe contener entradas y salidas externas al bloque invertido, no traspasos entre productos. Las fechas de valor influyen.</p></div>');return;}const read=$('#read-'+el.dataset.chart),display=chart.pts[idx];if(read)read.innerHTML='<strong>'+esc(p.period.length===7?monthLabel(p.period,true):p.period)+'</strong><strong>'+(chart.opts.percent?percent(p.value,2,true):chart.normalized?fmt(display.value,2)+' (base 100)':money(p.value,2))+'</strong>';}
document.addEventListener('click',e=>{const v=e.target.closest('[data-view]');if(v){navigate(v.dataset.view);return;}const b=e.target.closest('[data-block]');if(b){selectedBlock=b.dataset.block;if(currentView!=='cartera')navigate('cartera');else render();return;}const g=e.target.closest('[data-product]');if(g){productDetail(g.dataset.product);return;}const st=e.target.closest('[data-stock]');if(st){stockDetail(st.dataset.stock);return;}const md=e.target.closest('[data-month-detail]');if(md){monthDetail(md.dataset.monthDetail);return;}const mo=e.target.closest('[data-month]');if(mo){selectedMonth=mo.dataset.month;render();monthDetail(selectedMonth);return;}const h=e.target.closest('[data-hero]');if(h){heroMode=h.dataset.hero;render();return;}const sv=e.target.closest('[data-saving-mode]');if(sv){ordinary=sv.dataset.savingMode==='ordinary';render();return;}const ev=e.target.closest('[data-evo]');if(ev){evoMode=ev.dataset.evo;render();return;}const point=e.target.closest('[data-chart]');if(point){handleChart(point);return;}const a=e.target.closest('[data-act]');if(a&&!a.disabled){a.disabled=true;Promise.resolve(action(a.dataset.act)).catch(errorSheet).finally(()=>{if(a.isConnected)a.disabled=false;maskFields();});}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('svg [role=button]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}if(e.key==='Enter'&&e.target.id==='unlock-password'){e.preventDefault();unlockLocal().catch(errorSheet);}});
document.addEventListener('change',e=>{if(e.target.id==='savings-year'){savingsYear=e.target.value;selectedMonth=data.savings.filter(m=>m.period.startsWith(savingsYear)).at(-1)?.period;render();}if(e.target.id==='evolution-year'){evoYear=e.target.value;render();}if(e.target.id==='stock-sort'){stockSort=e.target.value;$('#stock-list').innerHTML=stockCards();}if(e.target.id==='snapshot-select'){payload.currentDate=e.target.value;selectData();render();}});
document.addEventListener('input',e=>{if(e.target.id==='stock-search'){stockQuery=e.target.value;$('#stock-list').innerHTML=stockCards();}});
$('#import-file').addEventListener('change',e=>{const f=e.target.files[0];if(f)handleFile(f);});
sheet.addEventListener('cancel',()=>{pending=null;});
let hiddenAt=0;document.addEventListener('visibilitychange',()=>{if(document.hidden){hiddenAt=Date.now();$('#screen-shield').hidden=false;}else{$('#screen-shield').hidden=true;if(persisted&&data&&Date.now()-hiddenAt>60000)lockApp().catch(errorSheet);}});
window.addEventListener('online',()=>toast('Conexion disponible. Tus datos siguen siendo locales.'));
window.addEventListener('offline',()=>toast('Sin conexion. Puedes seguir consultando el archivo cargado.'));
window.addEventListener('hashchange',()=>{if(data)navigate(location.hash.slice(1));});
(async()=>{try{envelope=await V.read();}catch(_){toast('Almacenamiento no disponible. Puedes trabajar sin guardar.');}render();if(location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1'){if('serviceWorker' in navigator){try{await navigator.serviceWorker.register('./sw.js');}catch(_){/* App still works online or in session. */}}}})();
})();
